import { execution } from '@dynatrace-sdk/automation-utils';
import { monitoredEntitiesClient } from '@dynatrace-sdk/client-classic-environment-v2';

export default async function () {
  const ex = await execution();
  const event = ex.params?.event;

  if (!event) {
    throw new Error(
      "No Davis event payload received. This workflow must be started by the Davis event trigger."
    );
  }

  const hostEntityId = event["dt.entity.host"];

  if (!hostEntityId) {
    throw new Error(
      "dt.entity.host was not found in the Davis event payload"
    );
  }

  const rawDrive = event["autoexpand.drive"];
  const drive = rawDrive?.replace(/\\+$/, "");

  const hostEntity = await monitoredEntitiesClient.getEntity({
    entityId: hostEntityId,
    fields: "+properties,+fromRelationships"
  });

  const ec2Relationship =
    hostEntity.fromRelationships?.runsOn?.find(
      entity => entity.type === "EC2_INSTANCE"
    );

  if (!ec2Relationship) {
    throw new Error(
      `No EC2_INSTANCE relationship found for host ${hostEntityId}`
    );
  }

  const ec2Entity = await monitoredEntitiesClient.getEntity({
    entityId: ec2Relationship.id,
    fields: "+properties"
  });

  const arn = ec2Entity.properties?.arn;
  const instanceId = ec2Entity.properties?.awsInstanceId;
  const region =
    ec2Entity.properties?.regionName ||
    event["aws.region"];

  if (!arn) {
    throw new Error(
      "AWS ARN was not found on the EC2 entity"
    );
  }

  if (!instanceId) {
    throw new Error(
      "AWS Instance ID was not found on the EC2 entity"
    );
  }

  const accountId = arn.split(":")[4];

  return {
    arn,
    accountId,
    instanceId,
    region,
    host: event["autoexpand.host"],
    drive,
    eventId: event["event.id"]
  };
}

import { execution } from '@dynatrace-sdk/automation-utils';
const ENDPOINT = "https://5nlyoe4s9c.execute-api.us-east-1.amazonaws.com/disk-autoexpand";
const TERMINAL = ['SUCCEEDED', 'FAILED', 'TIMED_OUT', 'ABORTED'];
async function startResult(ex) {
  const response = await ex.result('to_api_gateway_1');
  const body = response?.json ?? response?.body;
  const data = typeof body === 'string' ? JSON.parse(body) : body;
  if (!data?.success || !data?.executionArn) throw new Error('No confirmed execution ARN returned by start request');
  return data;
}
async function readStatus(executionArn) {
  const response = await fetch(ENDPOINT, {
    method: 'POST',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify({ action: 'status', executionArn }),
    signal: AbortSignal.timeout(15000)
  });
  if (!response.ok) throw new Error(`Status API returned HTTP ${response.status}`);
  const data = await response.json();
  if (!data.success || data.executionArn !== executionArn ||
      ![...TERMINAL, 'RUNNING', 'PENDING_REDRIVE'].includes(data.status)) {
    throw new Error('Invalid status response');
  }
  return data;
}

export default async function () {
  const ex = await execution();
  const started = await startResult(ex);
  const status = await readStatus(started.executionArn);
  if (!TERMINAL.includes(status.status)) throw new Error(`Expansion still pending: ${status.status}`);
  return status;
}

