export default async function () {
  const ex = await execution();
  let host = {};
  try { host = await ex.result('run_javascript_1') ?? {}; } catch (_) {}
  let started;
  let status;
  try {
    started = await startResult(ex);
  } catch (error) {
    status = { status: 'START_UNCONFIRMED', cause: String(error) + '. Check AWS before retrying; the request may have been accepted.' };
  }
  if (started) {
    try { status = await ex.result('poll_expansion'); } catch (_) {}
    if (!status || !TERMINAL.includes(status.status)) {
      try {
        status = await readStatus(started.executionArn);
        if (!TERMINAL.includes(status.status)) {
          status = { ...status, status: 'MONITORING_TIMEOUT', cause: 'Polling ended while AWS is still pending. Expansion outcome is unknown; AWS was not cancelled.' };
        }
      } catch (error) {
        status = { status: 'MONITORING_ERROR', cause: `Unable to retrieve final AWS status: ${String(error)}. Expansion outcome is unknown.` };
      }
    }
  }
  const escape = value => String(value ?? 'unknown').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
  const success = status.status === 'SUCCEEDED';
  const executionArn = started?.executionArn ?? 'unavailable';
  const detail = success ? 'Expansion workflow completed; SSM resize command reported success. Partition growth has not been independently verified.' : [status.error, status.cause].filter(Boolean).join(': ');
  const message = [
    `*Disk Auto Expansion: ${escape(status.status)}*`,
    `Host: ${escape(host.host || host.instanceId)}`,
    `Instance: ${escape(host.instanceId)} | Drive: ${escape(host.drive)}`,
    `Account: ${escape(host.accountId)} | Region: ${escape(host.region)}`,
    escape(detail.slice(0, 2000))
  ].join('\n');
  return { status: status.status, success, executionArn, message };
}

import { execution } from '@dynatrace-sdk/automation-utils';
export default async function () {
  const ex = await execution();
  const result = await ex.result('prepare_result');
  if (!result.success) throw new Error(`Disk expansion result: ${result.status}; execution: ${result.executionArn}`);
  return result;
}
